import {
  builtInSkills,
  detectWorksWith,
  SCENES,
  SKILLS,
  SLOT_SEQUENCES,
  type BuiltInRecipeId,
  type DirectorSkill,
  type SkillEntry,
} from '@motionpop/ai';

/**
 * Runtime catalogue for `/recipes` and `/skills` (spec 40).
 *
 * Where skills live right now:
 *   1. Reel Director Skills (Recipes): `skills/recipes/<id>.md` mirrored in `packages/ai/src/skills/recipes.ts`
 *   2. Motion-Graphic Slot Skills: `skills/<id>.md` mirrored in `packages/ai/src/slots/catalogue.ts`
 *      and `packages/ai/src/skills/slot-sequences.ts` (generated by `pnpm --filter @motionpop/ai skills:build`)
 *
 * Neither is stored in a live Firestore collection yet — they ship as versioned repo Markdown
 * compiled into `@motionpop/ai` so App Hosting / Cloud Run need zero runtime disk reads.
 * `catalog.test.ts` checks every entry below directly against `skills/*.md` so nothing can drift.
 */

export interface ShotSegment {
  startPct: number;
  endPct: number;
  rangeLabel: string;
  action: string;
}

export interface SlotSkillDetail {
  id: string;
  name: string;
  filePath: string;
  energy: 'low' | 'medium' | 'high';
  defaultDurationMs: number;
  useWhen: string;
  worksWith: readonly string[];
  /** Detection-level scene ids (replaces legacy component ids with active scenes). */
  scenes: readonly { id: string; name: string }[];
  intent: string;
  shots: readonly ShotSegment[];
  camera: string;
  emphasis: string;
  soundCues: string;
  rules: readonly string[];
  antiPatterns: string;
  voiceSync: string;
}

interface SlotSkillMeta {
  name: string;
  energy: 'low' | 'medium' | 'high';
  intent: string;
  camera: string;
  emphasis: string;
  soundCues: string;
  rules: readonly string[];
  antiPatterns: string;
  voiceSync: string;
}

