/**
 * Which motion-graphic slot skills (`skills/*.md`) naturally pair with each recipe when a creator
 * uses voiceover / script mode or mixes explainer scenes with that topic.
 */
export const RECIPE_PAIRED_SLOT_SKILLS: Readonly<Record<BuiltInRecipeId, readonly string[]>> = {
  'tech-explainer': [
    'calm-explanation',
    'contrast-split',
    'countdown-ranking',
    'journey-along-a-timeline',
    'brand-sting',
  ],
  'finance-business': [
    'shocking-stat-reveal',
    'slow-build-trend',
    'contrast-split',
    'journey-along-a-timeline',
  ],
  gaming: ['countdown-ranking', 'contrast-split', 'shocking-stat-reveal', 'brand-sting'],
  'podcast-story': ['calm-explanation', 'journey-along-a-timeline', 'zoom-from-world-to-place'],
  'hot-take': ['contrast-split', 'shocking-stat-reveal', 'countdown-ranking', 'brand-sting'],
};

const SCENE_NAME_BY_ID = new Map<string, string>(SCENES.map((s) => [s.id, s.name]));

/** Parses lines like `- 0–15%: small context line enters` into typed timeline segments. */
export function parseShotSequence(raw: string): ShotSegment[] {
  const out: ShotSegment[] = [];
  for (const line of raw.split('\n')) {
    const m = /^-\s*(\d+)\s*[–-]\s*(\d+)%:\s*(.+)$/.exec(line.trim());
    if (!m) continue;
    const startPct = Number(m[1]);
    const endPct = Number(m[2]);
    const action = (m[3] ?? '').trim();
    if (Number.isFinite(startPct) && Number.isFinite(endPct) && endPct > startPct && action) {
      out.push({ startPct, endPct, rangeLabel: `${startPct}–${endPct}%`, action });
    }
  }
  return out;
}

/** All 5 Reel Director Skills (Recipes), directly from `@motionpop/ai`. */
export function reelDirectorSkills(): readonly DirectorSkill[] {
  return builtInSkills.recipes();
}

/** All 8 Motion-Graphic Slot Skills, combining `@motionpop/ai` runtime data with full skill spec. */
export function slotSkills(): SlotSkillDetail[] {
  return SKILLS.map((entry: SkillEntry) => {
    const meta = SLOT_SKILL_META[entry.id];
    const sceneIds = detectWorksWith(entry);
    const shots = parseShotSequence(SLOT_SEQUENCES[entry.id] ?? '');
    return {
      id: entry.id,
      name: meta?.name ?? entry.id,
      filePath: `skills/${entry.id}.md`,
      energy: meta?.energy ?? 'medium',
      defaultDurationMs: entry.defaultDurationMs,
      useWhen: entry.useWhen,
      worksWith: entry.worksWith,
      scenes: sceneIds.map((id) => ({ id, name: SCENE_NAME_BY_ID.get(id) ?? id })),
      intent: meta?.intent ?? entry.useWhen,
      shots,
      camera: meta?.camera ?? '',
      emphasis: meta?.emphasis ?? '',
      soundCues: meta?.soundCues ?? '',
      rules: meta?.rules ?? [],
      antiPatterns: meta?.antiPatterns ?? '',
      voiceSync: meta?.voiceSync ?? '',
    };
  });
}

const SLOT_SKILL_MAP = new Map<string, SlotSkillDetail>(slotSkills().map((s) => [s.id, s]));

export function pairedSlotSkillsFor(recipeId: BuiltInRecipeId): SlotSkillDetail[] {
  return (RECIPE_PAIRED_SLOT_SKILLS[recipeId] ?? [])
    .map((id) => SLOT_SKILL_MAP.get(id))
    .filter((s): s is SlotSkillDetail => Boolean(s));
}
